prompt.text:
Repair the source below and return a complete CommonJS source file exporting exactly `{ priceOrderLines }`.

`products` must be an array of objects with a non-empty string `sku` and a finite, non-negative numeric `price`; SKUs must be unique. `lines` must be an array of objects with a non-empty string `sku` and a positive integer `quantity`. Throw `TypeError` for malformed data and `RangeError` when a line references an unknown SKU.

Return fresh objects shaped `{ sku, quantity, unitPrice, total }` in line order, where `total` is `unitPrice * quantity`. Empty arrays are valid. Do not mutate or alias either input array or its objects.

Known-bad source:

'use strict';

function priceOrderLines(products, lines) {
  if (!Array.isArray(products) || !Array.isArray(lines)) {
    throw new TypeError('products and lines must be arrays');
  }
  const prices = new Map();
  for (const product of products) {
    if (!product || typeof product !== 'object' || typeof product.sku !== 'string' ||
        product.sku.length === 0 || typeof product.price !== 'number' ||
        !Number.isFinite(product.price) || product.price < 0 || prices.has(product.sku)) {
      throw new TypeError('invalid product');
    }
    prices.set(product.sku, product.price);
  }

  return lines.map(function (line) {
    if (!line || typeof line !== 'object' || typeof line.sku !== 'string' ||
        line.sku.length === 0 || !Number.isInteger(line.quantity) || line.quantity <= 0) {
      throw new TypeError('invalid order line');
    }
    if (!prices.has(line.sku)) {
      throw new RangeError('unknown sku');
    }
    const unitPrice = prices.get(line.sku);
    return { sku: line.sku, quantity: line.quantity, unitPrice, total: unitPrice };
  });
}

module.exports = { priceOrderLines };

