'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['priceOrderLines']);
const { priceOrderLines } = api;

const products = [{ sku: 'A', price: 2.5 }, { sku: 'B', price: 0 }];
const lines = [{ sku: 'A', quantity: 4 }, { sku: 'B', quantity: 1 }, { sku: 'A', quantity: 1 }];
const productsSnapshot = JSON.stringify(products);
const linesSnapshot = JSON.stringify(lines);
const result = priceOrderLines(products, lines);
assert.deepEqual(result, [
  { sku: 'A', quantity: 4, unitPrice: 2.5, total: 10 },
  { sku: 'B', quantity: 1, unitPrice: 0, total: 0 },
  { sku: 'A', quantity: 1, unitPrice: 2.5, total: 2.5 }
]);
assert.equal(JSON.stringify(products), productsSnapshot);
assert.equal(JSON.stringify(lines), linesSnapshot);
assert.notStrictEqual(result, lines);
assert.notStrictEqual(result[0], lines[0]);
result[0].quantity = 99;
assert.equal(lines[0].quantity, 4);

const emptyProducts = [];
const emptyLines = [];
const emptyResult = priceOrderLines(emptyProducts, emptyLines);
assert.deepEqual(emptyResult, []);
assert.notStrictEqual(emptyResult, emptyLines);

assert.throws(() => priceOrderLines(null, []), TypeError);
assert.throws(() => priceOrderLines([], null), TypeError);
assert.throws(() => priceOrderLines([null], []), TypeError);
assert.throws(() => priceOrderLines([{ sku: '', price: 1 }], []), TypeError);
assert.throws(() => priceOrderLines([{ sku: 'A', price: -1 }], []), TypeError);
assert.throws(() => priceOrderLines([{ sku: 'A', price: NaN }], []), TypeError);
assert.throws(() => priceOrderLines([{ sku: 'A', price: 1 }, { sku: 'A', price: 2 }], []), TypeError);
assert.throws(() => priceOrderLines(products, [null]), TypeError);
assert.throws(() => priceOrderLines(products, [{ sku: '', quantity: 1 }]), TypeError);
for (const quantity of [0, -1, 1.5, NaN, '2']) {
  assert.throws(() => priceOrderLines(products, [{ sku: 'A', quantity }]), TypeError);
}
assert.throws(() => priceOrderLines(products, [{ sku: 'missing', quantity: 1 }]), RangeError);

